  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Mary&May Affiliate Program', 'https://marynmay.com/pages/affiliate', null, 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://marynmay.com/pages/affiliate', 'brand_site', 'affiliate_program', 'The brand''s own affiliate page (fetched): ''Join Mary&May Affiliate Program — earn up to 20% commissions on every qualified sale through your unique link or coupon code.'' Anyone can apply (creators, bloggers, or skincare fans); earnings are tracked in real time in an Affiliate Dashboard (login at affiliate.marynmay.com) and withdrawn via PayPal once the balance reaches $100 USD; affiliate-only Blackberry Triple Care products are stated to earn ''your regular 20% commissions''; the affiliate code gives customers a 20% discount; support contact is marketing@marynmay.com. Because the headline rate is a ceiling (''up to 20%''), commission_rate is recorded as null. The page makes no earnings-cap statement, so commission_cap is unknown, and publishes no creator count, so creator_saturation is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://marynmay.com/blogs/press/k-beauty-brand-mary-may-accelerates-global-offline-expansion-across-the-middle-east', 'brand_site', 'brand_overview', 'Brand press article on marynmay.com (published 2026-01-02): Mary&May is a flagship brand of AIDKOREA COMPANY expanding offline across the Middle East, North America, Europe and Southeast Asia through retail partners including Lifestyle, MONOPRIX and Gratis, confirming an established, actively expanding consumer brand behind the affiliate program.', 'publicly_reported', now());
