  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/cabeau-inc/', 'affiliate_directory', 'affiliate_program', 'Lasso (fetched) instead lists Cabeau at 8% per sale with a 45-day cookie and its join link routes to ShareASale, conflicting with LinkClicky''s Rakuten Advertising listing at 5%. Because the two fetched directories conflict on both network and rate, commission_rate is null and the conflict is documented here; the live join route (ShareASale) is recorded as the network. No fetched source states any earnings cap or an absolute creator count, so commission_cap and creator_saturation are unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 8, 8, 8, 4, '["Travel comfort accessories are a staple category for travel creators and flight-content niches.", "A category-leading neck pillow brand with an affiliate presence across directories.", "Published rates and networks conflict (5% via Rakuten per LinkClicky vs 8% via ShareASale per Lasso), so the rate is honestly null; no earnings cap is stated, so the cap stays unknown.", "Applications run through the network listings; no public brand partnerships email was found.", "Open application through the network listings, subject to approval.", "A well-known US travel accessories brand, founded in 2009 and widely retailed."]'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Ora Organic', 'https://ora.organic', 'Plant-based supplement brand (organic protein, probiotics, creatine and greens) selling clean, third-party-tested, vegan products. Its own ''Ora partner'' program page offers commission on referred sales plus free product and social features; third-party program sources report the affiliate program running on ShareASale at 20% commission, including 20% lifetime commissions on subscriptions.', 'United States', 'published') returning id into bid;
