  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Ora Organic Partner Program — commission on referred sales (reported 20%, incl. lifetime subscription commissions, via ShareASale)', 'https://ora.organic/pages/partnership', 'https://ora.organic/pages/partnership', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ora.organic/pages/partnership', 'official_site', 'affiliate', 'Ora Organic''s own Partnership page (fetched in full for this batch): ''Join the Ora inner circle — apply to become an Ora partner and get your favorite supplements, swag, commission on sales and more.'' Listed perks include free product and swag, commission on referred sales, early access, features on the brand''s socials, giveaways and exclusive discounts, with an application form on the page. The page does not publish a commission rate, and no earnings-cap statement or creator count appears, so cap and saturation stay unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://getlasso.co/affiliate/ora-organic/', 'network', 'affiliate', 'Lasso''s Ora Organic program listing: header rate shown as ''Varies'' with a 30-day cookie, while the listing body states ''Affiliates earn 20% on all purchases and 20% lifetime commissions on all subscriptions.'' The recorded 20% rate follows the convergent reporting across sources.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://3hundrd.com/vegan-affiliate-programs', 'listing', 'affiliate', '3hundrd''s vegan program roundup states the Ora Organic affiliate program is managed by ShareASale at 20% commission; it lists a 90-day cookie, which conflicts with Lasso''s 30 days — the network and rate agree across sources, the cookie duration does not, and the conflict is recorded here rather than resolved by guesswork.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 15, 16, 9, 8, 4, '{"compensation": "A reported 20% on purchases plus 20% lifetime commissions on subscriptions is strong for supplements; the brand''s own page confirms commission on sales but does not publish the rate.", "contact_access": "A public application form sits on the brand''s own partnership page; no public partnerships email was found on a fetched page.", "credibility": "Established USDA-organic, certified-vegan supplement brand with third-party testing published on its own pages.", "niche_fit": "Plant-based protein, gut-health and greens content is a core health-creator niche, and the products demo easily in routines and recipes.", "opportunity_availability": "The partner application is open on the brand''s site now.", "ugc_evidence": "The brand runs its own partner program with social features and giveaways for partners \u2014 a structured creator route, not just a network listing."}'::jsonb);
