  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 20, 7, 9, 4, '{"compensation": "A published 40% per sale with a 30-day cookie is top-band compensation for a consumer food brand.", "contact_access": "Application route is documented through the program''s ShareASale listing; no public partnerships email was found on a fetched page.", "credibility": "Established baby-nutrition brand built around pediatric allergen-introduction guidance, sold nationally.", "niche_fit": "Early allergen introduction is a high-intent topic for parent and baby-feeding creators, with a clear daily-use demo format.", "opportunity_availability": "Program is live and joinable now through ShareASale.", "ugc_evidence": "The program listing is written for influencers and bloggers; no separate brand-run creator page was fetched."}'::jsonb);
