  insert into public.brands (name, website, description, country, status) values ('Chamberlain Coffee', 'https://chamberlaincoffee.com/', 'Emma Chamberlain''s coffee and matcha brand (beans, cold brew, matcha and accessories). Its affiliate program runs on Rakuten Advertising, and the brand publishes hi@chamberlaincoffee.com for influencer and affiliate support. The commission rate is left null: published figures conflict across eras and networks (see evidence).', 'United States', 'published') returning id into bid;
