  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Chamberlain Coffee Affiliate Program on Rakuten Advertising — rate unpublished (conflicting reports); creator contact email published', 'https://linkclicky.com/affiliate-program/chamberlain-coffee/', 'https://linkclicky.com/affiliate-program/chamberlain-coffee/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://linkclicky.com/affiliate-program/chamberlain-coffee/', 'network', 'affiliate', 'LinkClicky''s Chamberlain Coffee profile (updated March 2024): affiliate platform Rakuten Advertising, commission 7% per sale, regions CA/GB/US, website chamberlaincoffee.com. The brand''s own site stack also lists Rakuten Advertising, corroborating the current network. An older (2021) source reported 20% via ShareASale, and Shopper.com''s 5-10% is a sub-network payout — the figures conflict across eras, so commission_rate is recorded as null with the conflict noted here. An affjumbo listing under the same name describes a different Spokane roaster and was excluded. No cap statement or creator count is published.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://usesnippet.app/pr-emails/chamberlain-coffee', 'listing', 'contact', 'Snippet''s contact research (checked against the brand''s own pages on November 13, 2026): Chamberlain Coffee lists hi@chamberlaincoffee.com ''for influencer & affiliate support'' — quoting the site: ''If you would like to contact us about our influencer and affiliate program, email us at'' — and business@chamberlaincoffee.com for press & collaborations. Snippet also notes the brand lists no program page of its own, so the email is the creator route in.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 14, 6, 11, 7, 5, '{"compensation": "No rate could be recorded: reports conflict (7% on Rakuten in 2024 vs 20% on ShareASale in 2021), so compensation scores low until the live network terms are checked.", "contact_access": "A published creator email (hi@chamberlaincoffee.com, explicitly for influencer & affiliate support) plus a separate press email.", "credibility": "Nationally distributed, celebrity-founded beverage brand with major retail placement.", "niche_fit": "A creator-founded coffee and matcha brand is native to drink-routine, GRWM and recipe content \u2014 among the strongest niche fits in this batch.", "opportunity_availability": "Program runs on Rakuten Advertising with application; the brand lists no program page of its own.", "ugc_evidence": "The brand maintains a named influencer/affiliate support route and runs its program on a major network; it was itself built by a creator."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Goldbelly', 'https://www.goldbelly.com', 'Online food marketplace shipping iconic regional dishes and restaurant specialties (pizza, bagels, cakes, barbecue) nationwide. Its affiliate program runs on ShareASale with a published 8% commission and an application requirement, per the whichprogram directory.', 'United States', 'published') returning id into bid;
