  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.influencerrate.com/affiliate-program/questnutrition', 'listing', 'affiliate', 'InfluencerRate''s Quest Nutrition affiliate program review (updated July 2025): commission rates 5-10% per sale (varies by product), cookie duration 30 days, payout monthly via PayPal or bank transfer; sign-up is through the official Quest Nutrition affiliate program page with approval in 24-48 hours. Following directory convention for published ranges, the recorded rate is the 5% floor. No earnings-cap statement and no creator count are published, so cap and saturation stay unknown. (Other ''Quest'' entities in search results — Quest Diagnostics, Quest Products Inc — are different companies and were excluded.)', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 12, 8, 7, 8, 5, '{"compensation": "The published range is 5%-10% per sale; recorded at the 5% floor, it is the lowest percentage in this batch, partly offset by a 30-day cookie and monthly payouts.", "contact_access": "Application route is documented through the program review; no public partnerships email was found on a fetched page.", "credibility": "One of the largest protein-snack brands in the US, with mass grocery distribution.", "niche_fit": "Protein bars, cookies and chips are everyday content for fitness, macro-tracking and snack-review creators.", "opportunity_availability": "Own-program application with a stated 24-48 hour approval window.", "ugc_evidence": "The program is documented as an influencer-facing affiliate program with its own application page; no creator counts are published."}'::jsonb);
