  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://desky.com.au/pages/collaboration-request', 'official_site', 'creator_program', 'Desky''s own Creators & Affiliates page (fetched in full) states verbatim: ''Every partner gets an affiliate link and competitive commission on the sales they refer, with no cap on what you can earn'' - an explicit no-earnings-cap statement in the brand''s own program terms, so commission_cap is uncapped. The page says the program runs on Impact, that commission rates are set per approved partner (''full terms come with your approval'', so no rate is published), offers product seeding, and publishes the contact help@desky.com.au; applications are manually reviewed and the program is positioned for editorial/review content rather than coupon sites. No creator count is published, so saturation is unknown.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 16, 10, 12, 7, 4, '{"compensation": "Verified UNCAPPED earnings on the brand''s own page (''no cap on what you can earn''), but the commission rate itself is not published (set per approved partner), which limits the compensation score.", "contact_access": "Published contact email (help@desky.com.au) plus an application form on the brand''s own program page.", "credibility": "Established Australian DTC workspace brand with physical showrooms and detailed published program terms.", "niche_fit": "Standing desks and workspace setups are a staple of desk-setup, WFH and tech creator content; high order values suit review content.", "opportunity_availability": "Applications are open but manually reviewed, and the program targets editorial/review partners rather than coupon or loyalty sites.", "ugc_evidence": "Dedicated creators program naming YouTubers, streamers, podcasters, bloggers, affiliates and social creators, with product seeding for reviews."}'::jsonb);
